class Solution { public List<Integer> largestDivisibleSubset(int[] nums){Arrays.sort(nums);int n=nums.length;int[] length=new int[n],previous=new int[n];Arrays.fill(length,1);Arrays.fill(previous,-1);int best=0;for(int i=0;i<n;i++){for(int j=0;j<i;j++)if(nums[i]%nums[j]==0&&length[j]+1>length[i]){length[i]=length[j]+1;previous[i]=j;}if(length[i]>length[best])best=i;}List<Integer> answer=new ArrayList<>();for(int index=best;index!=-1;index=previous[index])answer.add(nums[index]);Collections.reverse(answer);return answer;} }
